    import gspread

    # Mock the service account authentication and spreadsheet operations
    # since we're just testing the resize method's logic
    class MockClient:
        def batch_update(self, *args, **kwargs):
            return {"replies": []}

    class MockWorksheet:
        def __init__(self):
            self.client = MockClient()
            self.id = 1
            self.spreadsheet_id = "test"
            self._properties = {"gridProperties": {}}

        def resize(self, rows=None, cols=None):
            """Copy of the resize method from worksheet.py"""
            grid_properties = {}

            if rows is not None:
                grid_properties["rowCount"] = rows

            if cols is not None:
                grid_properties["columnCount"] = cols

            if not grid_properties:
                raise TypeError("Either 'rows' or 'cols' should be specified.")

            fields = ",".join("gridProperties/%s" % p for p in grid_properties.keys())

            body = {
                "requests": [
                    {
                        "updateSheetProperties": {
                            "properties": {
                                "sheetId": self.id,
                                "gridProperties": grid_properties,
                            },
                            "fields": fields,
                        }
                    }
                ]
            }

            res = self.client.batch_update(self.spreadsheet_id, body)
            if rows is not None:
                self._properties["gridProperties"]["rowCount"] = rows
            if cols is not None:
                self._properties["gridProperties"]["columnCount"] = cols
            return res

    # Test the resize method
    ws = MockWorksheet()
    print("Testing resize with rows=10")
    ws.resize(rows=10)
    print("Success!")

except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
EOF
